#!/usr/bin/env bash
# Prepares the iOS build inputs that the desktop prebuild script does not cover:
#
#   * a hard check of the iOS toolchain, because nothing here can be built without
#     a full Xcode installation (`src-tauri/gen/apple` is generated by the Tauri
#     CLI, which drives xcodebuild and the iphoneos SDK);
#   * the geo databases, which are gitignored and fetched on demand.
#
# Unlike Android there is no core binary to install here. iOS forbids starting a
# separate executable, so the mihomo core has to be linked into the app (and into
# a Network Extension) instead of being run as a sidecar. That work is not
# implemented yet; see docs/IOS.md.
#
# Run before `tauri ios init` / `tauri ios build`.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

RESOURCES_DIR="src-tauri/resources"
IOS_CONFIG="src-tauri/tauri.ios.conf.json"

# ------------------------------------------------------------- prerequisites
if [ ! -f "$IOS_CONFIG" ]; then
  echo "!! $IOS_CONFIG is missing; the iOS target has no platform configuration." >&2
  exit 1
fi

# `xcode-select -p` pointing at the command line tools means xcodebuild and
# xcrun cannot provide the iOS SDK, so stop before downloading anything.
DEVELOPER_DIR="$(xcode-select -p 2>/dev/null || true)"
case "$DEVELOPER_DIR" in
  *Xcode*.app/Contents/Developer) ;;
  *)
    echo "!! A full Xcode installation is required; the active developer directory is" >&2
    echo "!! '${DEVELOPER_DIR:-<none>}' (the command line tools alone cannot build iOS)." >&2
    echo "!! Install Xcode, then run:" >&2
    echo "!!   sudo xcode-select -s /Applications/Xcode.app" >&2
    exit 1
    ;;
esac

# A freshly installed Xcode needs one first launch before xcodebuild works.
if ! xcodebuild -version >/dev/null 2>&1; then
  echo "!! xcodebuild failed; Xcode has not finished its first-launch setup." >&2
  echo "!! Open Xcode once and accept the license, or run: xcodebuild -runFirstLaunch" >&2
  exit 1
fi

if ! xcrun --sdk iphoneos --show-sdk-path >/dev/null 2>&1; then
  echo "!! The iphoneos SDK could not be located. Run: xcodebuild -runFirstLaunch" >&2
  exit 1
fi

if ! command -v rustup >/dev/null 2>&1; then
  echo "!! rustup/cargo were not found on PATH; the Rust backend cannot be built." >&2
  echo "!! Install it with: curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh" >&2
  exit 1
fi

for target in aarch64-apple-ios aarch64-apple-ios-sim; do
  if ! rustup target list --installed | grep -qx "$target"; then
    echo "==> Adding the $target rust target"
    rustup target add "$target"
  fi
done

# ---------------------------------------------------------------- deployment
# Print the value the build actually uses instead of a hardcoded copy of it.
IOS_DEPLOYMENT_TARGET="$(python3 -c '
import json, sys
print(json.load(open(sys.argv[1]))["bundle"]["iOS"].get("minimumSystemVersion", ""))
' "$IOS_CONFIG" 2>/dev/null || true)"
IOS_DEPLOYMENT_TARGET="${IOS_DEPLOYMENT_TARGET:-15.0}"

# ------------------------------------------------------------- geo databases
# Every platform except Android reads these from the bundled resources, so they
# have to exist before the bundle is assembled.
mkdir -p "$RESOURCES_DIR"

fetch_resource() {
  local file="$1"
  local url="$2"
  if [ ! -f "$RESOURCES_DIR/$file" ]; then
    echo "==> Downloading resource $file"
    curl -fL --retry 3 -o "$RESOURCES_DIR/$file" "$url"
  fi
}

RULE_BASE="https://github.com/MetaCubeX/meta-rules-dat/releases/download/latest"
fetch_resource Country.mmdb "$RULE_BASE/country.mmdb"
fetch_resource ASN.mmdb "$RULE_BASE/GeoLite2-ASN.mmdb"
fetch_resource geosite.dat "$RULE_BASE/geosite.dat"
fetch_resource geoip.dat "$RULE_BASE/geoip.dat"

# ------------------------------------------------------------- what is left
# Deliberately not installed here:
#   * a sidecar core: iOS cannot execute one, and it must not be shipped inside
#     the app bundle either;
#   * the mihomo core as a library: upstream publishes no iOS artifact, so it has
#     to be built from source (see docs/IOS.md).
echo "==> iOS deployment target: ${IOS_DEPLOYMENT_TARGET} (from ${IOS_CONFIG})"
echo "==> iOS inputs ready; still required before the app can run:"
echo "    * bundle.iOS.developmentTeam (or APPLE_DEVELOPMENT_TEAM) for code signing;"
echo "    * a Network Extension target with the packet-tunnel-provider entitlement;"
echo "    * an in-process build of the mihomo core."
